pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    function testFuzz_property(address from, address recipient, uint256 v) public {
        vm.assume(from != address(0));
        vm.assume(recipient != address(0));
        StatefulCallee callee = new StatefulCallee();

        address[] memory tos = new address[](1);
        tos[0] = recipient;

        bool ok;
        try c.transfer(from, address(callee), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(callee.wasCalled() == ok && callee.wasCalled());
    }
}

contract StatefulCallee {
    bool public called;

    function transferFrom(address, address, uint256) external returns (bool) {
        called = true;
        return true;
    }

    function wasCalled() external view returns (bool) {
        return called;
    }
}
